            "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"65\" font-size=\"34\" fill=\"#ffd700\" font-weight=\"bold\" text-anchor=\"middle\">Quick Check</text><rect x=\"120\" y=\"180\" width=\"860\" height=\"300\" rx=\"18\" fill=\"rgba(59,130,246,0.1)\" stroke=\"#3b82f6\" stroke-width=\"3\"/><text x=\"550\" y=\"260\" font-size=\"26\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"bold\">What is \"normal science\"?</text><text x=\"550\" y=\"330\" font-size=\"20\" fill=\"#888\" text-anchor=\"middle\">puzzle-solving inside an accepted</text><text x=\"550\" y=\"365\" font-size=\"20\" fill=\"#888\" text-anchor=\"middle\">paradigm, not questioning it</text><rect x=\"220\" y=\"600\" width=\"660\" height=\"240\" rx=\"16\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"3\"/><text x=\"550\" y=\"670\" font-size=\"22\" fill=\"#10b981\" font-weight=\"bold\" text-anchor=\"middle\">Puzzle-solving,</text><text x=\"550\" y=\"710\" font-size=\"22\" fill=\"#10b981\" font-weight=\"bold\" text-anchor=\"middle\">trusting the framework</text></svg>",
